import { test, expect } from '@playwright/test';

test.describe('Image Upload Preview', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display image preview when a file is uploaded', async ({ page }) => {
    // Locate and interact with the file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('playwright/fixtures/sample-image.jpg');

    // Wait for the preview container to appear
    const previewContainer = page.getByRole('region', { name: /image preview/i });
    await expect(previewContainer).toBeVisible();

    // Verify the image preview element exists and has the correct source
    const previewImage = page.getByRole('img', { name: /image preview/i });
    await expect(previewImage).toBeVisible();
    await expect(previewImage).toHaveAttribute('src', /sample-image\.jpg/);

    // Verify the preview container has a border or styling
    const previewBox = page.locator('[data-testid="preview-box"]');
    await expect(previewBox).toHaveCSS('border', /1px solid/);

    // Verify the submit button is enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeEnabled();
  });

  test('should not display preview when file upload is cancelled or invalid', async ({ page }) => {
    // Locate and interact with the file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('playwright/fixtures/sample-image.jpg');

    // Verify preview appears initially
    const previewContainer = page.getByRole('region', { name: /image preview/i });
    await expect(previewContainer).toBeVisible();

    // Cancel the file selection
    await fileInput.setInputFiles('playwright/fixtures/sample-image.jpg', { force: true });
    await fileInput.setInputFiles('playwright/fixtures/sample-image.jpg', { force: true });

    // Wait for the preview to be removed
    await page.waitForTimeout(500);

    // Verify preview container is no longer visible
    await expect(previewContainer).not.toBeVisible();

    // Verify the preview image element is removed
    const previewImage = page.getByRole('img', { name: /image preview/i });
    await expect(previewImage).not.toBeVisible();

    // Verify the submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();
  });
});
